"""Next firing times of a five-field cron expression. See task.md."""

from __future__ import annotations

from datetime import date, datetime, timedelta


class CronError(ValueError):
    """Raised for malformed expressions and for searches that find nothing."""


MONTHS = ["JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"]
DAYS = ["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"]


def _value(text: str, lo: int, hi: int, names: dict[str, int]) -> int:
    if text.isascii() and text.isdigit():
        v = int(text)
    elif text.upper() in names:
        v = names[text.upper()]
    else:
        raise CronError(f"bad value {text!r}")
    if not lo <= v <= hi:
        raise CronError(f"value {v} out of range {lo}-{hi}")
    return v


def _parse_field(text: str, lo: int, hi: int, names: dict[str, int]) -> set[int]:
    out: set[int] = set()
    for term in text.split(","):
        if not term:
            raise CronError(f"empty term in {text!r}")
        base, slash, step_text = term.partition("/")
        step = 1
        if slash:
            if not (step_text.isascii() and step_text.isdigit()):
                raise CronError(f"bad step in {term!r}")
            step = int(step_text)
            if step < 1:
                raise CronError(f"step must be >= 1 in {term!r}")
        if base == "*":
            a, b = lo, hi
        elif "-" in base:
            left, _, right = base.partition("-")
            a = _value(left, lo, hi, names)
            b = _value(right, lo, hi, names)
            if a > b:
                raise CronError(f"range low above high in {term!r}")
        else:
            a = _value(base, lo, hi, names)
            b = hi if slash else a
        out.update(range(a, b + 1, step))
    return out


def _add_years(d: datetime, years: int) -> datetime:
    try:
        return d.replace(year=d.year + years)
    except ValueError:
        return d.replace(year=d.year + years, day=28)
    except OverflowError:
        raise CronError("date out of range")


def next_firings(expr: str, start: datetime, count: int) -> list[datetime]:
    """Return the next `count` firing times strictly after `start`."""
    fields = expr.split()
    if len(fields) != 5:
        raise CronError("expected five fields")
    minute_f, hour_f, dom_f, month_f, dow_f = fields
    minutes = sorted(_parse_field(minute_f, 0, 59, {}))
    hours = sorted(_parse_field(hour_f, 0, 23, {}))
    doms = _parse_field(dom_f, 1, 31, {})
    months = _parse_field(month_f, 1, 12, {n: i + 1 for i, n in enumerate(MONTHS)})
    dows = {d % 7 for d in _parse_field(dow_f, 0, 7, {n: i for i, n in enumerate(DAYS)})}
    dom_restricted = dom_f != "*"
    dow_restricted = dow_f != "*"

    def day_ok(d: date) -> bool:
        if d.month not in months:
            return False
        dom_ok = d.day in doms
        dow_ok = (d.weekday() + 1) % 7 in dows
        if dom_restricted and dow_restricted:
            return dom_ok or dow_ok
        if dom_restricted:
            return dom_ok
        if dow_restricted:
            return dow_ok
        return True

    results: list[datetime] = []
    cursor = start.replace(second=0, microsecond=0)
    for _ in range(max(count, 0)):
        limit = _add_years(cursor, 5)
        day = cursor.date()
        found = None
        while True:
            if day_ok(day):
                for h in hours:
                    for m in minutes:
                        cand = datetime(day.year, day.month, day.day, h, m)
                        if cand > cursor:
                            found = cand
                            break
                    if found:
                        break
            if found or datetime(day.year, day.month, day.day) > limit:
                break
            try:
                day += timedelta(days=1)
            except OverflowError:
                break
        if found is None or found > limit:
            raise CronError("no firing within five years")
        results.append(found)
        cursor = found
    return results
